        /// <summary>Projects a source read. Pure: the same source and capture always produce the same snapshot and projection digest.</summary>
        public static CapabilitySnapshot Project(SemanticSource source, SemanticCapture? capture = null)
        {
            ArgumentNullException.ThrowIfNull(source);
            capture ??= new SemanticCapture();
            var context = new SemanticProjectionContext(CapabilityProjectionContract.Rows, source.Identity);
            if (source.Identity == null)
            {
                context.Report("IdentityUnbound", SemanticSeverity.Error, null, null, null, "The source read carries no identity argument.");
            }

            if (string.Equals(source.Procedure, CapabilityProjectionContract.Procedure, StringComparison.Ordinal) == false)
            {
                context.Report("ProcedureMismatch", SemanticSeverity.Error, null, null, null, "The source was not read through the contract's procedure.");
            }

            ImmutableArray<SemanticSection>.Builder sections = ImmutableArray.CreateBuilder<SemanticSection>();
            ImmutableArray<Capability>.Builder capabilityEntities = ImmutableArray.CreateBuilder<Capability>();
            ImmutableArray<ScenarioContract>.Builder contractsEntities = ImmutableArray.CreateBuilder<ScenarioContract>();
            ImmutableArray<Scenario>.Builder scenariosEntities = ImmutableArray.CreateBuilder<Scenario>();
            ImmutableArray<ExecutionOperation>.Builder executionOperationsEntities = ImmutableArray.CreateBuilder<ExecutionOperation>();
            ImmutableArray<Port>.Builder portsEntities = ImmutableArray.CreateBuilder<Port>();
            ImmutableArray<ProviderBinding>.Builder bindingsEntities = ImmutableArray.CreateBuilder<ProviderBinding>();
            ImmutableArray<Provider>.Builder providersEntities = ImmutableArray.CreateBuilder<Provider>();
            bool documentPresent = false;
            bool rootSectionSeen = false;
            using (JsonDocument? document = context.OpenDocument(source, CapabilityProjectionContract.ExpectedSections, out ImmutableArray<SemanticDocumentSection> documentSections))
            {
                documentPresent = document != null;
                foreach (SemanticDocumentSection section in documentSections)
                {
                    if (section.Expected == false)
                    {
                        sections.Add(context.Retain(section));
                        continue;
                    }

                    switch (section.Name)
                    {
                        case "capability_summary":
                            rootSectionSeen = true;
                            sections.Add(context.ProjectTyped(section, capabilityEntities, TryProjectCapability));
                            break;
                        case "contracts":
                            sections.Add(context.ProjectTyped(section, contractsEntities, TryProjectScenarioContract));
                            break;
                        case "scenarios":
                            sections.Add(context.ProjectTyped(section, scenariosEntities, TryProjectScenario));
                            break;
                        case "execution_operations":
                            sections.Add(context.ProjectTyped(section, executionOperationsEntities, TryProjectExecutionOperation));
                            break;
                        case "ports":
                            sections.Add(context.ProjectTyped(section, portsEntities, TryProjectPort));
                            break;
                        case "bindings":
                            sections.Add(context.ProjectTyped(section, bindingsEntities, TryProjectProviderBinding));
                            break;
                        case "providers":
                            sections.Add(context.ProjectTyped(section, providersEntities, TryProjectProvider));
                            break;
                        default:
                            sections.Add(context.Retain(section));
                            break;
                    }
                }
            }

            if (rootSectionSeen && capabilityEntities.Count != 1)
            {
                context.Report("RootCardinality", SemanticSeverity.Error, "capability_summary", null, null, "Exactly one root entity is required; found " + capabilityEntities.Count.ToString(CultureInfo.InvariantCulture) + ".");
            }

            var capabilityEntitiesByKey = new Dictionary<string, Capability>();
            foreach (Capability entity in capabilityEntities)
            {
                if (capabilityEntitiesByKey.TryAdd(entity.CapabilityId, entity) == false)
                {
                    context.Report("DuplicateKey", SemanticSeverity.Error, "capability_summary", entity.SourceRow, "capability_id", "Another entity in this section has the same key; references to it are ambiguous.");
                }
            }

            var contractsEntitiesByKey = new Dictionary<ValueTuple<long?, string, long?>, ScenarioContract>();
            foreach (ScenarioContract entity in contractsEntities)
            {
                if (contractsEntitiesByKey.TryAdd(new ValueTuple<long?, string, long?>(entity.ScenarioVersionPk, entity.ContractRole, entity.ContractVersionPk), entity) == false)
                {
                    context.Report("DuplicateKey", SemanticSeverity.Error, "contracts", entity.SourceRow, "scenario_version_pk,contract_role,contract_version_pk", "Another entity in this section has the same key; references to it are ambiguous.");
                }
            }

            var scenariosEntitiesByKey = new Dictionary<ValueTuple<long?>, Scenario>();
            foreach (Scenario entity in scenariosEntities)
            {
                if (scenariosEntitiesByKey.TryAdd(new ValueTuple<long?>(entity.ScenarioVersionPk), entity) == false)
                {
                    context.Report("DuplicateKey", SemanticSeverity.Error, "scenarios", entity.SourceRow, "scenario_version_pk", "Another entity in this section has the same key; references to it are ambiguous.");
                }
            }

            var executionOperationsEntitiesByKey = new Dictionary<ValueTuple<long?>, ExecutionOperation>();
            foreach (ExecutionOperation entity in executionOperationsEntities)
            {
                if (executionOperationsEntitiesByKey.TryAdd(new ValueTuple<long?>(entity.ExecutionOperationPk), entity) == false)
                {
                    context.Report("DuplicateKey", SemanticSeverity.Error, "execution_operations", entity.SourceRow, "execution_operation_pk", "Another entity in this section has the same key; references to it are ambiguous.");
                }
            }

            var portsEntitiesByKey = new Dictionary<ValueTuple<string, long?>, Port>();
            foreach (Port entity in portsEntities)
            {
                if (portsEntitiesByKey.TryAdd(new ValueTuple<string, long?>(entity.PortId, entity.PortVersionPk), entity) == false)
                {
                    context.Report("DuplicateKey", SemanticSeverity.Error, "ports", entity.SourceRow, "port_id,port_version_pk", "Another entity in this section has the same key; references to it are ambiguous.");
                }
            }

            var bindingsEntitiesByKey = new Dictionary<ValueTuple<long?, long?>, ProviderBinding>();
            foreach (ProviderBinding entity in bindingsEntities)
            {
                if (bindingsEntitiesByKey.TryAdd(new ValueTuple<long?, long?>(entity.ProviderSlotPk, entity.ProviderBindingPk), entity) == false)
                {
                    context.Report("DuplicateKey", SemanticSeverity.Error, "bindings", entity.SourceRow, "provider_slot_pk,provider_binding_pk", "Another entity in this section has the same key; references to it are ambiguous.");
                }
            }

            var providersEntitiesByKey = new Dictionary<string, Provider>();
            foreach (Provider entity in providersEntities)
            {
                if (providersEntitiesByKey.TryAdd(entity.ProviderId, entity) == false)
                {
                    context.Report("DuplicateKey", SemanticSeverity.Error, "providers", entity.SourceRow, "provider_id", "Another entity in this section has the same key; references to it are ambiguous.");
                }
            }

            string? documentSha256 = source.DocumentText == null ? null : SemanticCanonicalJson.Sha256Hex(source.DocumentText);
            long? documentBytes = source.DocumentText == null ? null : Encoding.UTF8.GetByteCount(source.DocumentText);
            var provenance = new SemanticProvenance(CapabilityProjectionContract.Id, CapabilityProjectionContract.Revision, CapabilityProjectionContract.Digest, CapabilityProjectionContract.Authority, CapabilityProjectionContract.Generator, source.Procedure, source.Arguments, source.RowResultSets, documentSha256, documentBytes, capture);
            var snapshot = new CapabilitySnapshot(source.Refusal, provenance, sections.ToImmutable(), source.Identity, documentPresent, capabilityEntities.ToImmutable(), capabilityEntitiesByKey, contractsEntities.ToImmutable(), contractsEntitiesByKey, scenariosEntities.ToImmutable(), scenariosEntitiesByKey, executionOperationsEntities.ToImmutable(), executionOperationsEntitiesByKey, portsEntities.ToImmutable(), portsEntitiesByKey, bindingsEntities.ToImmutable(), bindingsEntitiesByKey, providersEntities.ToImmutable(), providersEntitiesByKey);

            foreach (ExecutionOperation entity in snapshot._executionOperations)
            {
                if (snapshot.ResolveScenario(entity).State == SemanticResolutionState.Dangling)
                {
                    context.Report("DanglingReference", SemanticSeverity.Warning, "execution_operations", entity.SourceRow, "scenario_version_pk", "The reference 'Scenario' names a key no entity of 'scenarios' carries in this snapshot; nothing was fetched.");
                }
            }

            foreach (ExecutionOperation entity in snapshot._executionOperations)
            {
                if (snapshot.ResolvePort(entity).State == SemanticResolutionState.Dangling)
                {
                    context.Report("DanglingReference", SemanticSeverity.Warning, "execution_operations", entity.SourceRow, "port_id,port_version_pk", "The reference 'Port' names a key no entity of 'ports' carries in this snapshot; nothing was fetched.");
                }
            }

            foreach (ScenarioContract entity in snapshot._contracts)
            {
                if (snapshot.ResolveScenario(entity).State == SemanticResolutionState.Dangling)
                {
                    context.Report("DanglingReference", SemanticSeverity.Warning, "contracts", entity.SourceRow, "scenario_version_pk", "The reference 'Scenario' names a key no entity of 'scenarios' carries in this snapshot; nothing was fetched.");
                }
            }

            foreach (ProviderBinding entity in snapshot._bindings)
            {
                if (snapshot.ResolveProvider(entity).State == SemanticResolutionState.Dangling)
                {
                    context.Report("DanglingReference", SemanticSeverity.Warning, "bindings", entity.SourceRow, "provider_id", "The reference 'Provider' names a key no entity of 'providers' carries in this snapshot; nothing was fetched.");
                }
            }

            snapshot.Diagnostics = context.Diagnostics;
            snapshot.Availability = source.Refusal != null ? source.Refusal.Availability : context.HasErrors ? SemanticAvailability.ContractMismatch : SemanticAvailability.Present;
            try
            {
                snapshot.ProjectionDigest = "sha256:" + SemanticCanonicalJson.Sha256Hex(snapshot.ToCanonicalPayload());
            }
            catch (InvalidOperationException exception)
            {
                context.Report("PayloadNotCanonical", SemanticSeverity.Error, null, null, null, "The projection payload cannot be canonicalized: " + exception.Message);
                snapshot.Diagnostics = context.Diagnostics;
                snapshot.Availability = source.Refusal != null ? source.Refusal.Availability : SemanticAvailability.ContractMismatch;
            }

            return snapshot;
        }

