        /// <summary>A bounded, human- and agent-readable view: identity, availability, provenance, coverage, up to <paramref name="maxEntitiesPerSection"/> entities per typed section with reference states, and diagnostics. Omissions are counted, never silent.</summary>
        public string ToInspectionJson(int maxEntitiesPerSection = 25, int maxDiagnostics = 200)
        {
            var buffer = new ArrayBufferWriter<byte>();
            using (var writer = new Utf8JsonWriter(buffer, new JsonWriterOptions { Indented = true, Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping }))
            {
                writer.WriteStartObject();
                writer.WriteString("inspection", "semantic-inspection.v1");
                writer.WriteStartObject("contract");
                writer.WriteString("id", CapabilityProjectionContract.Id);
                writer.WriteString("revision", CapabilityProjectionContract.Revision);
                writer.WriteString("authority", CapabilityProjectionContract.Authority);
                writer.WriteString("digest", CapabilityProjectionContract.Digest);
                writer.WriteString("generator", CapabilityProjectionContract.Generator);
                writer.WriteEndObject();
                writer.WriteString("availability", Availability.ToString());
                SemanticWriting.Identity(writer, Identity);
                SemanticWriting.Refusal(writer, Refusal);
                writer.WriteString("projectionDigest", ProjectionDigest);
                writer.WriteString("payloadAlgorithm", SemanticCanonicalJson.Algorithm);
                SemanticWriting.Provenance(writer, Provenance);
                SemanticWriting.Coverage(writer, Sections, CapabilityProjectionContract.ExpectedSections.Length);
                writer.WriteStartObject("entities");
                writer.WriteStartObject("Capability");
                writer.WriteString("section", "capability_summary");
                writer.WriteNumber("count", _capability.Length);
                writer.WriteNumber("omitted", Math.Max(0, _capability.Length - maxEntitiesPerSection));
                writer.WriteStartArray("items");
                foreach (Capability entity in _capability.Take(maxEntitiesPerSection))
                {
                    InspectCapability(writer, entity);
                }

                writer.WriteEndArray();
                writer.WriteEndObject();
                writer.WriteStartObject("Contracts");
                writer.WriteString("section", "contracts");
                writer.WriteNumber("count", _contracts.Length);
                writer.WriteNumber("omitted", Math.Max(0, _contracts.Length - maxEntitiesPerSection));
                writer.WriteStartArray("items");
                foreach (ScenarioContract entity in _contracts.Take(maxEntitiesPerSection))
                {
                    InspectScenarioContract(writer, entity);
                }

                writer.WriteEndArray();
                writer.WriteEndObject();
                writer.WriteStartObject("Scenarios");
                writer.WriteString("section", "scenarios");
                writer.WriteNumber("count", _scenarios.Length);
                writer.WriteNumber("omitted", Math.Max(0, _scenarios.Length - maxEntitiesPerSection));
                writer.WriteStartArray("items");
                foreach (Scenario entity in _scenarios.Take(maxEntitiesPerSection))
                {
                    InspectScenario(writer, entity);
                }

                writer.WriteEndArray();
                writer.WriteEndObject();
                writer.WriteStartObject("ExecutionOperations");
                writer.WriteString("section", "execution_operations");
                writer.WriteNumber("count", _executionOperations.Length);
                writer.WriteNumber("omitted", Math.Max(0, _executionOperations.Length - maxEntitiesPerSection));
                writer.WriteStartArray("items");
                foreach (ExecutionOperation entity in _executionOperations.Take(maxEntitiesPerSection))
                {
                    InspectExecutionOperation(writer, entity);
                }

                writer.WriteEndArray();
                writer.WriteEndObject();
                writer.WriteStartObject("Ports");
                writer.WriteString("section", "ports");
                writer.WriteNumber("count", _ports.Length);
                writer.WriteNumber("omitted", Math.Max(0, _ports.Length - maxEntitiesPerSection));
                writer.WriteStartArray("items");
                foreach (Port entity in _ports.Take(maxEntitiesPerSection))
                {
                    InspectPort(writer, entity);
                }

                writer.WriteEndArray();
                writer.WriteEndObject();
                writer.WriteStartObject("Bindings");
                writer.WriteString("section", "bindings");
                writer.WriteNumber("count", _bindings.Length);
                writer.WriteNumber("omitted", Math.Max(0, _bindings.Length - maxEntitiesPerSection));
                writer.WriteStartArray("items");
                foreach (ProviderBinding entity in _bindings.Take(maxEntitiesPerSection))
                {
                    InspectProviderBinding(writer, entity);
                }

                writer.WriteEndArray();
                writer.WriteEndObject();
                writer.WriteStartObject("Providers");
                writer.WriteString("section", "providers");
                writer.WriteNumber("count", _providers.Length);
                writer.WriteNumber("omitted", Math.Max(0, _providers.Length - maxEntitiesPerSection));
                writer.WriteStartArray("items");
                foreach (Provider entity in _providers.Take(maxEntitiesPerSection))
                {
                    InspectProvider(writer, entity);
                }

                writer.WriteEndArray();
                writer.WriteEndObject();
                writer.WriteEndObject();
                SemanticWriting.Diagnostics(writer, Diagnostics, maxDiagnostics);
                writer.WriteEndObject();
            }

            return Encoding.UTF8.GetString(buffer.WrittenSpan);
        }

